for i, (m, f, a, b, c) in enumerate(FWD):
    C.append(("K" if i < 10 else "U", ["‘%s’ کی مؤنث ہے:", "لفظ ‘%s’ کو مؤنث بنائیے:", "‘%s’ کی تانیث کون سی ہے؟"][i % 3] % m, f, a, b, c,
        "‘%s’ مذکر ہے اور اس کی مؤنث ‘%s’ ہے؛ باقی صورتیں اردو میں رائج نہیں ہیں۔" % (m, f)))
